input.content:
[
  {
    "question": "The app has one screen today, the guestbook. Should the to-do list come in beside it, or replace it?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "Beside it, keep the guestbook", "recommended": true,
       "consequence": "Both screens stay, with a way to switch between them."},
      {"key": "B", "label": "Replace the guestbook", "recommended": false,
       "consequence": "The guestbook and all its entries go away in this same change, which makes the change much bigger."}
    ]
  },
  {
    "question": "Once a task is marked done, can it be switched back to not done?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "Yes, it can be switched back", "recommended": true,
       "consequence": "A mis-click is fixed with one more click."},
      {"key": "B", "label": "No, done is final", "recommended": false,
       "consequence": "A task ticked by mistake stays done, or has to be deleted and added again."}
    ]
  },
  {
    "question": "You wrote 'ew usuniecie lub edycja' (possibly delete or edit). Which of these belong in this change?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "Both delete and edit", "recommended": true,
       "consequence": "Any task can be corrected or removed; a little more to build and test."},
      {"key": "B", "label": "Delete only", "recommended": false,
       "consequence": "A typo is fixed by deleting the task and adding it again."},
      {"key": "C", "label": "Neither for now", "recommended": false,
       "consequence": "Only adding and ticking; a wrong task stays in the list for good."}
    ]
  },
  {
    "question": "What happens to a task in the list once it is marked done?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "Stays in place, shown as done", "recommended": true,
       "consequence": "The list never jumps around; done and open tasks stay mixed."},
      {"key": "B", "label": "Moves below the open tasks", "recommended": false,
       "consequence": "Open tasks are always on top; the list reorders on every tick."},
      {"key": "C", "label": "Disappears from the list", "recommended": false,
       "consequence": "The list shows only what is left to do; a done task can no longer be seen or switched back."}
    ]
  }
]

