input.content:
[
  {
    "question": "With two screens, which one should open when somebody goes to the app's main address?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "The guestbook, as today", "recommended": true,
       "consequence": "Nothing people already use moves; the to-do list is one click away in the navigation."},
      {"key": "B", "label": "The to-do list", "recommended": false,
       "consequence": "The new list is the first thing people see; the guestbook moves one click away."}
    ]
  },
  {
    "question": "In what order should the tasks be listed?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "Newest at the top", "recommended": true,
       "consequence": "A task you just added shows up right under the field; older tasks move down."},
      {"key": "B", "label": "Oldest at the top", "recommended": false,
       "consequence": "The list reads in the order tasks were written, like a paper list; a new task appears at the bottom."}
    ]
  },
  {
    "question": "Every screen in this app is in English today, by a project rule. Which language should the to-do screen use?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "English, like the rest", "recommended": true,
       "consequence": "Consistent with the guestbook; no project rule changes."},
      {"key": "B", "label": "Polish", "recommended": false,
       "consequence": "The to-do screen would be the only Polish one, and the all-English rule has to be lifted for it."}
    ]
  },
  {
    "question": "When a fresh copy of the app is set up (for example a preview to look at), should the to-do list start with a few example tasks?",
    "allow_free_text": true,
    "options": [
      {"key": "A", "label": "Yes, a few example tasks", "recommended": true,
       "consequence": "Whoever opens a fresh copy sees a filled list to judge, the same way the guestbook starts with example entries."},
      {"key": "B", "label": "No, start empty", "recommended": false,
       "consequence": "A fresh copy shows an empty list until someone types tasks in."}
    ]
  }
]

